SELECT DISTINCT hd.device_id AS "deviceId", hd.assigned_person AS "identityCard", sp.name AS "personName", hd.status AS "deviceStatus" FROM swm_helmet_device hd LEFT JOIN swm_person sp ON hd.assigned_person = sp.identity_card WHERE hd.assigned_person IN
#{idCard}
AND hd.status = '0' AND sp.personnel_status = '1' AND sp.status = '0'

SELECT DISTINCT hd.device_id AS "deviceId", hd.assigned_person AS "identityCard", sp.name AS "personName", sp.gender AS "gender", sp.phone_number AS "phoneNumber", hd.status AS "deviceStatus" FROM swm_helmet_device hd LEFT JOIN swm_person sp ON hd.assigned_person = sp.identity_card WHERE hd.device_id IN
#{deviceId}
AND hd.status = '0' AND sp.personnel_status = '1' AND sp.status = '0' ORDER BY sp.name
